let gamesState=null; let activeTab="overview"; let activeTeamChallengeId=""; const $=id=>document.getElementById(id);
function esc(v){return String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));}
function fmtDate(v){if(!v)return"TBD";const d=new Date(v);return Number.isFinite(d.getTime())?d.toLocaleString(undefined,{weekday:"short",month:"short",day:"numeric",hour:"numeric",minute:"2-digit"}):v;}

function titleCaseStatus(v){return String(v||"").replace(/[_-]+/g," ").replace(/\b\w/g,m=>m.toUpperCase());}
function submissionSortTime(x){return new Date(x?.reviewedAt||x?.submittedAt||x?.createdAt||0).getTime()||0;}
function latestSubmissionFor(weekId,challengeId,teamId){const list=(gamesState?.submissions||[]).filter(x=>x.weekId===weekId&&x.challengeId===challengeId&&(!teamId||x.teamId===teamId));return list.sort((a,b)=>submissionSortTime(b)-submissionSortTime(a))[0]||null;}
function deriveChallengeStatus(week,c){const fullWeek=String(c?.durationMode||"").toLowerCase()==="week"||["contracts","shopping-list","location-hunt"].includes(String(c?.trackingMode||"").toLowerCase());if(fullWeek){const now=Date.now(),open=new Date(c?.opensAt||week?.startDate||0).getTime(),close=new Date(c?.closesAt||week?.endDate||8640000000000000).getTime();if(Number.isFinite(open)&&now<open)return {label:"Opens Soon",key:"upcoming"};if(Number.isFinite(close)&&now>close)return {label:"Ended",key:"completed"};return {label:"Active",key:"started"};}if(c?.trackingMode==="boss-rush"){const a=Array.isArray(c.myBossRushAttempts)?c.myBossRushAttempts:[],running=a.find(x=>x.status==="running");if(running){const end=new Date(running.endsAt||0).getTime();return Number.isFinite(end)&&Date.now()>=end?{label:"Finalizing",key:"completed"}:{label:"In Progress",key:"started"};}if(a.length>=Math.max(1,Number(c.attemptsPerPlayer||1)))return {label:"Completed",key:"completed"};return {label:"Available",key:"available"};}const s=c?.session;const sub=gamesState?.myTeam?latestSubmissionFor(week?.id,c?.id,gamesState.myTeam.id):null;if(sub){const st=String(sub.status||"submitted").toLowerCase();if(st==="approved")return {label:"Approved",key:"approved"};if(st==="rejected")return {label:"Rejected",key:"rejected"};return {label:"Submitted",key:"submitted"};}if((c?.kind||"main")==="side"){const now=Date.now(),open=new Date(c.opensAt||week?.startDate||0).getTime(),close=new Date(c.closesAt||week?.endDate||8640000000000000).getTime();if(Number.isFinite(open)&&now<open)return {label:"Opens Soon",key:"upcoming"};if(Number.isFinite(close)&&now>close)return {label:"Closed",key:"completed"};return {label:"Live",key:"started"};}if(s?.status==="submitted")return {label:"Submitted",key:"submitted"};if(s?.startedAt){const end=s?.endsAt?new Date(s.endsAt).getTime():NaN;if(Number.isFinite(end)&&Date.now()>=end)return {label:"Completed",key:"completed"};return {label:"In Progress",key:"started"};}if(s?.scheduledAt)return {label:"Booked",key:"booked"};return {label:"Not Booked",key:"available"};}
function deriveScheduleStatus(s){const review=String(s?.submissionStatus||"").toLowerCase();if(review==="approved")return {label:"Approved",key:"approved"};if(review==="rejected")return {label:"Rejected",key:"rejected"};if(review||s?.status==="submitted")return {label:"Submitted",key:"submitted"};if(s?.startedAt){const end=s?.endsAt?new Date(s.endsAt).getTime():NaN;if(Number.isFinite(end)&&Date.now()>=end)return {label:"Completed",key:"completed"};return {label:"In Progress",key:"started"};}if(s?.scheduledAt)return {label:"Booked",key:"booked"};return {label:"Not Booked",key:"available"};}
function currentWeek(){const q=new URLSearchParams(location.search),testWeekId=q.get("test")==="1"?q.get("testWeekId")||"":"";if(testWeekId){const picked=gamesState?.weeks?.find(w=>String(w.id)===String(testWeekId));if(picked)return picked;}const now=Date.now();return gamesState?.weeks?.find(w=>{const a=new Date(w.startDate||0).getTime(),b=new Date(w.endDate||8640000000000000).getTime();return now>=a&&now<=b;})||gamesState?.weeks?.find(w=>(w.challenges||[]).some(c=>c.status==="active"))||gamesState?.weeks?.[0];}
function isWeekPublished(weekId){return (gamesState?.publishedResultWeeks||[]).map(String).includes(String(weekId));}
function standings(){return [...(gamesState?.teams||[])].sort((a,b)=>(Number(b.points)||0)-(Number(a.points)||0));}
function standingHtml(){return `<div class="games-standings">${standings().map((t,i)=>`<div class="games-standing"><span class="rank">${i+1}</span><div><strong>${esc(t.name)}</strong><div class="games-muted">${(t.members||[]).length} members</div></div><strong>${Number(t.points)||0} pts</strong></div>`).join("")||"No teams configured yet."}</div>`;}
function finalStandingsHtml(){const rows=(gamesState?.gamesCompleted&&gamesState?.finalStandings?.length)?gamesState.finalStandings:standings().map((t,i)=>({rank:i+1,teamId:t.id,teamName:t.name,points:Number(t.points)||0}));return `<div class="games-final-standings">${rows.map(r=>`<div class="games-final-standing ${Number(r.rank)===1?"is-champion":""}"><span class="rank">${Number(r.rank)||"—"}</span><strong>${esc(r.teamName||"Team")}</strong><b>${Number(r.points)||0} pts</b></div>`).join("")}</div>`;}
function championNames(){const ids=(gamesState?.winnerTeamIds||[]).map(String);const rows=(gamesState?.finalStandings||[]).filter(r=>ids.includes(String(r.teamId)));if(rows.length)return rows.map(r=>r.teamName).join(" & ");return gamesState?.winnerTeamName||"Champion";}

function publishedSubmissions(){const pub=new Set((gamesState?.publishedResultWeeks||[]).map(String));return (gamesState?.submissions||[]).filter(s=>pub.has(String(s.weekId))&&String(s.status||"").toLowerCase()==="approved");}
function publishedWeekRows(){const teams=gamesState?.teams||[];if(gamesState?.gamesCompleted&&Array.isArray(gamesState?.finalProgression)&&gamesState.finalProgression.length){return gamesState.finalProgression.map((r,idx)=>({week:{id:r.weekId,name:r.weekName},index:idx+1,published:true,totals:new Map(teams.map(t=>[String(t.id),Number(r.totals?.[String(t.id)])||0]))}));}const subs=publishedSubmissions();let totals=new Map(teams.map(t=>[String(t.id),0]));return (gamesState?.weeks||[]).map((w,idx)=>{const published=isWeekPublished(w.id);if(published){for(const s of subs.filter(x=>String(x.weekId)===String(w.id)))totals.set(String(s.teamId),(totals.get(String(s.teamId))||0)+(Number(s.points)||0));}return {week:w,index:idx+1,published,totals:new Map(totals)};});}
function teamPublishedWins(teamId){if(gamesState?.gamesCompleted&&Array.isArray(gamesState?.finalStandings)){const row=gamesState.finalStandings.find(r=>String(r.teamId)===String(teamId));if(row)return Number(row.wins)||0;}const pub=new Set((gamesState?.publishedResultWeeks||[]).map(String)),subs=(gamesState?.submissions||[]).filter(s=>pub.has(String(s.weekId))&&String(s.status||"").toLowerCase()==="approved");let wins=0;for(const w of gamesState?.weeks||[]){if(!pub.has(String(w.id)))continue;for(const c of w.challenges||[]){const rows=subs.filter(s=>String(s.weekId)===String(w.id)&&String(s.challengeId)===String(c.id));if(!rows.length)continue;const best=Math.max(...rows.map(r=>Number(r.points)||0));if(rows.some(r=>String(r.teamId)===String(teamId)&&(Number(r.points)||0)===best&&best>0))wins++;}}return wins;}
function pointsChartHtml(){const teams=gamesState?.teams||[],rows=publishedWeekRows().filter(r=>r.published);if(!rows.length)return `<div class="games-chart-empty"><strong>Points history begins when Week 1 is published.</strong><span>Private and approved-but-unpublished scores never appear here.</span></div>`;const labels=["Start",...rows.map(r=>r.week.name||`Week ${r.index}`)],series=teams.map(t=>({team:t,vals:[0,...rows.map(r=>Number(r.totals.get(String(t.id)))||0)]}));const max=Math.max(5,...series.flatMap(s=>s.vals)),W=900,H=300,L=58,R=24,T=28,B=48,iw=W-L-R,ih=H-T-B,x=i=>L+(labels.length===1?0:(i/(labels.length-1))*iw),y=v=>T+ih-(v/max)*ih;const grid=[0,.25,.5,.75,1].map(p=>{const val=Math.round(max*p);return `<line x1="${L}" y1="${y(val)}" x2="${W-R}" y2="${y(val)}" class="games-chart-grid"/><text x="${L-12}" y="${y(val)+4}" text-anchor="end" class="games-chart-axis">${val}</text>`}).join("");const xs=labels.map((l,i)=>`<text x="${x(i)}" y="${H-16}" text-anchor="middle" class="games-chart-axis">${esc(l)}</text>`).join("");const lines=series.map((s,si)=>{const pts=s.vals.map((v,i)=>`${x(i)},${y(v)}`).join(" ");const dots=s.vals.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" class="games-chart-dot team-${si}"/>`).join("");return `<polyline points="${pts}" class="games-chart-line team-${si}"/>${dots}`}).join("");const legend=series.map((s,i)=>`<span><i class="games-chart-key team-${i}"></i>${esc(s.team.name)}</span>`).join("");return `<div class="games-chart-wrap"><div class="games-chart-legend">${legend}</div><svg class="games-points-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Published team points over time">${grid}${xs}${lines}</svg></div>`;}
function weekProgressHtml(){const weeks=gamesState?.weeks||[];if(!weeks.length)return `<span class="games-muted">No weeks configured.</span>`;return `<div class="games-week-track">${weeks.map((w,i)=>{const pub=isWeekPublished(w.id),cur=currentWeek()?.id===w.id;return `<div class="games-week-step ${pub?"is-published":cur?"is-current":"is-upcoming"}"><span>${pub?"✓":cur?"●":"○"}</span><div><strong>${esc(w.name||`Week ${i+1}`)}</strong><small>${pub?"Published":cur?"In Progress · Results Hidden":"Upcoming"}</small></div></div>`}).join("")}</div>`;}

function renderOverview(){
  const week=currentWeek(),teams=standings(),weeks=gamesState?.weeks||[],publishedCount=(gamesState?.publishedResultWeeks||[]).length;
  if(gamesState.gamesCompleted)return `<section class="games-overview-hero games-complete-hero"><div><p class="eyebrow">🏆 IRONKIN GAMES COMPLETE</p><h2>${esc(championNames())}</h2><p>Final standings locked ${fmtDate(gamesState.completedAt)}.</p></div></section><div class="games-grid games-overview-grid"><article class="games-card games-standings-card"><p class="eyebrow">FINAL STANDINGS</p><h2>Leaderboard</h2>${finalStandingsHtml()}</article><article class="games-card"><p class="eyebrow">EVENT ARCHIVE</p><h2>Results & History</h2><p class="games-muted">Browse every published week, challenge placement and final score.</p><button class="games-btn secondary" data-jump-tab="results">View Results</button></article></div>`;
  const weekIndex=Math.max(0,weeks.findIndex(w=>String(w.id)===String(week?.id))),weekNumber=weekIndex+1;
  const standingsBody=gamesState.hasPublishedResults?standingHtml():`<div class="games-results-locked-note"><strong>Standings begin after Week 1 results</strong><p class="games-muted">Current scores remain private until staff publishes the week.</p></div>`;
  // Overview must never expose challenge identity, tracker type, or other clues before reveal.
  const challenges=(week?.challenges||[]).map(c=>{const revealed=Boolean(c.revealed),st=deriveChallengeStatus(week,c),kind=(c.kind||"main")==="side"?"SIDE":"MAIN",name=revealed?(c.name||"Challenge"):(kind==="SIDE"?"Mystery Side Challenge":"Mystery Main Challenge"),tracking=String(c.trackingMode||"").toLowerCase(),trackLabel=revealed?(tracking==="contracts"?"Contracts · WOM":tracking==="shopping-list"?"Shopping List · Drops":tracking==="location-hunt"?"Location Hunt · Photo Proof":tracking==="boss-rush"?"Boss Rush · WOM":c.proofMode==="none"?"Automatic tracking":"Challenge tracking"):"Details sealed",revealMeta=!revealed&&c.opensAt?`<span>Reveals ${esc(fmtDate(c.opensAt))}</span>`:"";return `<article class="games-overview-challenge ${revealed?"":"is-sealed"}"><div class="games-overview-challenge-top"><span class="games-kind-badge ${kind==="SIDE"?"is-side":""}">${kind}</span><span class="games-status-badge status-${esc(st.key)}">${esc(st.label)}</span></div><h3>${esc(name)}</h3><p>${esc(challengeCardSummary(c,kind==="SIDE",revealed))}</p><div class="games-overview-challenge-meta"><span>${esc(trackLabel)}</span><span>${esc(c.participants||"8 players")}</span>${revealMeta}</div></article>`;}).join("");
  const myTeam=gamesState.myTeam,rank=myTeam?teams.findIndex(t=>String(t.id)===String(myTeam.id))+1:0;
  const prev=[...weeks].slice(0,Math.max(0,weekIndex)).reverse().find(w=>isWeekPublished(w.id));
  const prevSubs=prev?(gamesState.submissions||[]).filter(s=>String(s.weekId)===String(prev.id)&&String(s.status||"").toLowerCase()==="approved"):[];
  const prevSummary=prev?`<div class="games-recent-week"><strong>${esc(prev.name||"Previous Week")}</strong><span>${prevSubs.length?`${prevSubs.length} approved results published`:`Results published`}</span></div>`:`<p class="games-muted">No previous week has been published yet.</p>`;
  const now=Date.now(),future=[];for(const w of weeks){for(const c of (w.challenges||[])){if(c.revealed)continue;const at=new Date(c.opensAt||w.startDate||0).getTime();if(Number.isFinite(at)&&at>now)future.push({at,kind:(c.kind||"main")==="side"?"Side Challenge":"Main Challenge"});}}future.sort((a,b)=>a.at-b.at);const next=future[0];
  const upNext=next?`<div class="games-up-next"><span>${esc(next.kind)}</span><strong>Next challenge reveal</strong><small>${esc(fmtDate(new Date(next.at).toISOString()))}</small></div>`:`<div class="games-up-next"><span>THIS WEEK</span><strong>${week?.challenges?.length?"All scheduled challenges are revealed":"No upcoming reveal scheduled"}</strong></div>`;
  return `<section class="games-dashboard-head"><div><p class="eyebrow">IRONKIN GAMES · LIVE</p><h2>${esc(week?.name||"Current Week")}</h2><p>${week?`${fmtDate(week.startDate)} → ${fmtDate(week.endDate)}`:"The next week will appear here when scheduled."}</p></div><div class="games-dashboard-week"><strong>${weekNumber || 1}</strong><span>WEEK OF ${weeks.length||5}</span></div></section>
  <div class="games-dashboard-layout"><section class="games-dashboard-main"><div class="games-section-head"><div><p class="eyebrow">THIS WEEK</p><h2>Current Challenges</h2></div><button class="games-text-action" data-jump-tab="week">Open This Week →</button></div><div class="games-overview-challenges">${challenges||`<p class="games-muted">No challenges scheduled for this week.</p>`}</div></section>
  <aside class="games-dashboard-side"><article class="games-card games-standings-card"><div class="games-card-heading"><div><p class="eyebrow">STANDINGS</p><h2>Leaderboard</h2></div><button class="games-text-action" data-jump-tab="results">Results →</button></div>${standingsBody}</article>${myTeam?`<article class="games-card games-my-team-card"><p class="eyebrow">YOUR TEAM</p><div class="games-my-team-summary"><div><h2>${esc(myTeam.name)}</h2><span>${rank?`#${rank} overall · `:""}${Number(myTeam.points)||0} pts</span></div><strong>${(myTeam.members||[]).length}</strong></div><button class="games-btn secondary" data-jump-tab="teams">Open Your Team</button></article>`:""}</aside></div>
  <section class="games-card games-overview-chart"><div class="games-card-heading"><div><p class="eyebrow">POINTS OVER TIME</p><h2>Games Progression</h2></div><span class="games-muted">Published results only</span></div>${pointsChartHtml()}</section>
  <section class="games-dashboard-bottom"><article class="games-card"><p class="eyebrow">UP NEXT</p><h2>Next Reveal</h2>${upNext}</article><article class="games-card"><p class="eyebrow">LAST PUBLISHED</p><h2>Recent Results</h2>${prevSummary}<button class="games-text-action" data-jump-tab="results">View all results →</button></article></section>
  <section class="games-card games-progress-card"><div class="games-card-heading"><div><p class="eyebrow">EVENT PROGRESS</p><h2>${publishedCount} of ${weeks.length||0} Weeks Published</h2></div></div>${weekProgressHtml()}</section>`;
}

function contractTestContext(){const q=new URLSearchParams(location.search);if(q.get("test")!=="1")return"";const t=q.get("testTeamId")||"",p=q.get("testPlayerDiscordId")||"";return t&&p?`&test=1&testTeamId=${encodeURIComponent(t)}&testPlayerDiscordId=${encodeURIComponent(p)}`:"";}
function contractTestBody(){const q=new URLSearchParams(location.search);return q.get("test")==="1"?{test:"1",testTeamId:q.get("testTeamId")||"",testPlayerDiscordId:q.get("testPlayerDiscordId")||""}:{};}
function contractPanelHtml(week,c){
  if(!c.revealed||(!gamesState.myTeam&&!gamesState.isStaff))return"";
  return `<div class="games-contracts" data-contract-panel="${esc(week.id)}|${esc(c.id)}"><div class="games-contract-loading">Loading team contracts…</div></div>`;
}
function renderContractPanel(el,data){
  const tiers=data.tiers||{},claims=data.claims||[],contracts=data.contracts||[],mine=claims.find(x=>String(x.playerDiscordId)===String(data.myDiscordId));
  const completed=claims.filter(x=>x.completed).length,points=claims.filter(x=>x.completed).reduce((n,x)=>n+(Number(x.points)||0),0),icons={safe:"✓",risky:"⚔", "all-in":"☠"},descs={safe:"Steady commitment",risky:"Serious grind", "all-in":"Maximum commitment"};
  const tierOrder=["safe","risky","all-in"];
  const groups=tierOrder.map(tier=>{const meta=tiers[tier]||{},used=claims.filter(x=>x.tier===tier).length,slots=Number(meta.slots)||0;const cards=contracts.filter(x=>x.tier===tier).map(c=>{const claim=claims.find(x=>x.contractId===c.id),pct=claim?Math.min(100,Math.round((Number(claim.progress)||0)/(Number(claim.target)||1)*100)):0,disabled=!data.isOpen||!!mine||!!claim||used>=slots;return `<article class="contract-choice risk-${esc(tier)} ${claim?"is-claimed":""} ${claim?.completed?"is-complete":""}"><div class="contract-choice-top"><span class="contract-risk-badge"><i>${icons[tier]||"◆"}</i>${esc(meta.label||tier)}</span><span class="contract-points">+${Number(meta.points)||0} PTS</span></div><div class="contract-choice-body"><strong>${esc(c.name)}</strong></div>${claim?`<div class="contract-claimant"><span>${claim.completed?"Completed by":"Claimed by"}</span><strong>${esc(claim.playerName)}</strong></div><div class="contract-progress"><i style="width:${pct}%"></i></div><div class="contract-progress-copy"><span>${Number(claim.progress).toLocaleString()} / ${Number(claim.target).toLocaleString()}</span><b>${claim.completed?"✓ COMPLETE":`${pct}%`}</b></div>${data.isStaff?`<button type="button" class="games-btn secondary compact" data-contract-admin-refresh="${esc(claim.id)}" data-contract-player="${esc(claim.playerName)}">Refresh WOM</button><button type="button" class="games-btn secondary compact contract-admin-reset" data-contract-reset="${esc(claim.id)}" data-contract-player="${esc(claim.playerName)}" data-contract-name="${esc(claim.name)}">Reset Selection</button>`:""}`:(data.canClaim?`<button class="games-btn secondary compact contract-claim-btn" data-contract-claim="${esc(c.id)}" ${disabled?"disabled":""}>${mine?"Already Chosen":used>=slots?`${esc(meta.label||tier)} Full`:"Claim Contract"}</button>`:`<span class="games-pill">Available</span>`)}</article>`;}).join("");return `<section class="contract-tier-group risk-${esc(tier)}" data-contract-tier-panel="${esc(tier)}"><header class="contract-tier-head"><div class="contract-tier-identity"><span class="contract-tier-icon">${icons[tier]||"◆"}</span><div><strong>${esc(meta.label||tier)}</strong><span>${descs[tier]||"Contract tier"} · ${Number(meta.points)||0} points on completion</span></div></div><div class="contract-tier-slots"><strong>${used}/${slots}</strong><span>CLAIMED</span></div></header><div class="contract-choice-grid">${cards||`<p class="games-muted">No ${esc(meta.label||tier)} contracts configured.</p>`}</div></section>`;}).join("");
  const filters=tierOrder.map((tier,i)=>{const meta=tiers[tier]||{},used=claims.filter(x=>x.tier===tier).length,slots=Number(meta.slots)||0;return `<button type="button" class="contract-tier-filter risk-${esc(tier)} ${i===0?"is-active":""}" data-contract-tier-filter="${esc(tier)}"><span class="contract-tier-icon">${icons[tier]||"◆"}</span><span><strong>${esc(meta.label||tier)}</strong><small>${used}/${slots} claimed · ${Number(meta.points)||0} pts</small></span></button>`;}).join("");
  const teamPicker=data.isStaff&&Array.isArray(data.teams)&&data.teams.length?`<div class="shopping-admin-team contract-admin-team"><label>ADMIN TEAM</label><select data-contract-team>${data.teams.map(t=>`<option value="${esc(t.id)}" ${String(t.id)===String(data.teamId)?"selected":""}>${esc(t.name)}</option>`).join("")}</select><span>View and manage Contract selections for any team without joining it.</span></div>`:"";
  const womRows=Array.isArray(data.refreshDiagnostics)?data.refreshDiagnostics:[],womFailures=womRows.filter(x=>!x.ok),womSuccess=womRows.filter(x=>x.ok);
  const womDiag=data.isStaff&&womRows.length?`<div class="games-participant-warning"><strong>WOM refresh: ${womSuccess.length}/${womRows.length} successful${womFailures.length?` · ${womFailures.length} failed`:""}</strong><span>${womRows.map(x=>x.ok?`${esc(x.rsn)} · ${esc(x.metric||"metric")} · WOM ${Number(x.currentValue||0).toLocaleString()} · baseline ${Number(x.baseline||0).toLocaleString()} · progress ${Number(x.progress||0).toLocaleString()} · snapshot ${esc(x.snapshotAt||"unknown")}`:`${esc(x.rsn)} · FAILED · ${esc(x.error||"Unknown WOM error")}`).join("<br>")}</span></div>`:"";
  el.innerHTML=`${womDiag}${teamPicker}<div class="contracts-summary"><div><span>CLAIMED</span><strong>${claims.length}<small>/ 8</small></strong></div><div><span>COMPLETED</span><strong>${completed}<small>/ 8</small></strong></div><div><span>TEAM SCORE</span><strong>${points}<small>/ 64 pts</small></strong></div><div class="contracts-summary-actions">${mine?`<button class="games-btn secondary compact" data-contract-refresh>Refresh My Progress</button>`:""}${data.testMode?`<button class="games-btn secondary compact" data-contract-reset-test>Reset Test Claims</button>`:""}</div></div>${mine?`<div class="contract-my-status is-selected"><span>YOUR CONTRACT</span><div><strong>${esc(mine.name)}</strong><small>WOM baseline captured ${fmtDate(mine.claimedAt)} · progress counts from that point forward.</small></div></div>`:data.canClaim?`<div class="contract-my-status is-prompt"><span>CHOOSE YOUR CONTRACT</span><div><strong>Choose one contract for yourself.</strong><small>Progress starts when you claim. Your team's required 2 / 4 / 2 lineup is shown above.</small></div></div>`:`<div class="contract-my-status is-prompt"><span>ADMIN VIEW · ${esc(data.teamName||"TEAM")}</span><div><strong>Review this team's Contract selections.</strong><small>Use Reset Selection on a claimed Contract if a player needs to choose again.</small></div></div>`}<div class="contract-tier-filterbar" aria-label="Filter contracts by risk">${filters}</div><div class="contract-tier-panels">${groups}</div>`;
  const setTier=tier=>{el.querySelectorAll("[data-contract-tier-filter]").forEach(b=>{const active=b.dataset.contractTierFilter===tier;b.classList.toggle("is-active",active);b.setAttribute("aria-pressed",active?"true":"false");});el.querySelectorAll("[data-contract-tier-panel]").forEach(p=>p.hidden=p.dataset.contractTierPanel!==tier);};
  el.querySelectorAll("[data-contract-tier-filter]").forEach(b=>b.addEventListener("click",()=>setTier(b.dataset.contractTierFilter)));
  setTier("safe");
}
