 return `<section class="team-challenge-panel tt-panel"><div class="team-panel-heading"><div><p class="eyebrow">MAIN CHALLENGE · YOUR TEAM</p><h2>${esc(c.name||"Ironkin Time Trials")}</h2><p>Eight activities, any teammate can compete. Your team's best approved result in each activity earns placement points; only the best five count.</p></div><span class="team-panel-tracking">SCREENSHOT VERIFIED</span></div><div class="tt-summary"><div><strong>8</strong><span>ACTIVITIES</span></div><div><strong>5</strong><span>BEST COUNT</span></div><div><strong>50</strong><span>TRIAL POINTS</span></div><div><strong>10</strong><span>RAID BONUS</span></div><div><strong>60</strong><span>MAX TOTAL</span></div></div><h3>Time Trial Activities</h3><div class="tt-list">${activityRows}</div><p class="games-muted">Activity placements award 10 / 7 / 4 / 1 points. No approved result earns zero. Improved results can be submitted during the event.</p><h3>Cooperative Raid Bonuses</h3><div class="tt-list">${raidRows}</div><p class="games-muted">+4 additional points for completing all three raids. Normal modes only; ToA minimum 150 invocation.</p><div class="tt-notice"><strong>Submission system not yet enabled</strong><p>This page displays the Week 3 challenge, but activity-specific screenshot uploads, approval histories, and automatic standings require the dedicated Time Trials backend. They are not active yet, so no results will be recorded from this panel.</p></div></section>`;
