function renderTeamChallengePanel(item){if(!item)return`<div class="team-hub-empty"><strong>No team trackers are available yet.</strong><span>Contracts and side-challenge progress will appear here when their challenge is revealed.</span></div>`;const c=item.challenge,w=item.week;if(item.type==="trials")return timeTrialsPanel(w,c);if(item.type==="contracts")return `<section class="team-challenge-panel"><div class="team-panel-heading"><div><p class="eyebrow">MAIN CHALLENGE · YOUR TEAM</p><h2>${esc(c.name||"Contracts")}</h2><p>Choose your contract, see every teammate's assignment and follow your team's completion progress.</p></div><span class="team-panel-tracking">WOM TRACKED</span></div>${contractPanelHtml(w,c)}</section>`;if(item.type==="shopping")return `<section class="team-challenge-panel"><div class="team-panel-heading"><div><p class="eyebrow">SIDE CHALLENGE · YOUR TEAM</p><h2>${esc(c.name||"Shopping List")}</h2><p>Items are submitted through the normal Ironkin drop system — automatically through RuneLite or manually with /submit.</p></div><span class="team-panel-tracking">DROP TRACKED</span></div><div class="team-shopping-list" data-team-shopping-list="${esc(w.id)}|${esc(c.id)}"><div class="games-contract-loading">Loading your team's shopping list…</div></div></section>`;if(item.type==="trivia")return `<section class="team-challenge-panel"><div class="team-panel-heading"><div><p class="eyebrow">MINI CHALLENGE · YOUR TEAM</p><h2>${esc(c.name||"Trivia Hunt")}</h2><p>Solve the daily clue, find the answer in-game, and race to submit valid photo proof.</p></div><span class="team-panel-tracking">DAILY PHOTO RACE</span></div><div class="team-trivia-hunt" data-team-trivia-hunt="${esc(w.id)}|${esc(c.id)}"><div class="games-contract-loading">Loading today's trivia…</div></div></section>`;if(item.type==="locations")return `<section class="team-challenge-panel"><div class="team-panel-heading"><div><p class="eyebrow">SIDE CHALLENGE · YOUR TEAM</p><h2>${esc(c.name||"Location Hunt")}</h2><p>One location unlocks each day. Recreate the scene, submit your screenshot, and keep hunting through Sunday.</p></div><span class="team-panel-tracking">DAILY REVEALS</span></div><div class="team-location-hunt" data-team-location-hunt="${esc(w.id)}|${esc(c.id)}"><div class="games-contract-loading">Loading your team's locations…</div></div></section>`;return `<section class="team-challenge-panel"><div class="team-panel-heading"><div><p class="eyebrow">SIDE CHALLENGE · YOUR TEAM</p><h2>${esc(c.name||"Clue Hunters")}</h2><p>Live clue completions and points for your team.</p></div><span class="team-panel-tracking">WOM TRACKED</span></div><div class="team-clue-progress" data-team-clue-progress="${esc(w.id)}|${esc(c.id)}"><div class="games-contract-loading">Loading your team's clue progress…</div></div></section>`;}
function renderTeams(){if(!gamesState.myTeam){if(gamesState.isStaff){const items=teamChallengeItems();const contracts=items.find(x=>x.type==="contracts")||null,shopping=items.find(x=>x.type==="shopping")||null,trivia=items.find(x=>x.type==="trivia")||null,trials=items.find(x=>x.type==="trials")||null;if(contracts||shopping||trivia||trials){const w=(contracts||shopping||trivia||trials).week;return `<section class="team-hub"><header class="team-hub-header"><div><p class="eyebrow">ADMIN · ${esc(w?.name||"CURRENT WEEK")}</p><h1>Ironkin Games Team Manager</h1><p>You are not rostered on a team. Select any team inside the panels below to view and manage their live progress.</p></div></header><div class="team-hub-content">${trials?timeTrialsPanel(trials.week,trials.challenge):""}${contracts?`<section class="team-challenge-panel"><div class="team-panel-heading"><div><p class="eyebrow">MAIN CHALLENGE · ADMIN</p><h2>${esc(contracts.challenge.name||"Contracts")}</h2><p>View every team's Contract selections and reset a player's selection when needed.</p></div><span class="team-panel-tracking">WOM TRACKED</span></div>${contractPanelHtml(contracts.week,contracts.challenge)}</section>`:""}${trivia?`<section class="team-challenge-panel"><div class="team-panel-heading"><div><p class="eyebrow">MINI CHALLENGE · ADMIN</p><h2>${esc(trivia.challenge.name||"Trivia Hunt")}</h2><p>Select a team to submit screenshots directly to that team’s Trivia Hunt history and review proofs.</p></div><span class="team-panel-tracking">PROOF MANAGEMENT</span></div><div class="team-trivia-hunt" data-team-trivia-hunt="${esc(trivia.week.id)}|${esc(trivia.challenge.id)}"><div class="games-contract-loading">Loading Trivia Hunt admin controls…</div></div></section>`:""}${shopping?`<section class="team-challenge-panel"><div class="team-panel-heading"><div><p class="eyebrow">SIDE CHALLENGE · ADMIN</p><h2>${esc(shopping.challenge.name||"Shopping List")}</h2><p>View team progress and manually add or correct drops without joining a team.</p></div><span class="team-panel-tracking">DROP TRACKED</span></div><div class="team-shopping-list" data-team-shopping-list="${esc(shopping.week.id)}|${esc(shopping.challenge.id)}"><div class="games-contract-loading">Loading team Shopping List…</div></div></section>`:""}</div></section>`;}}return`<div class="games-card full team-hub-empty"><strong>You are not assigned to an Ironkin Games team.</strong><span>Your private challenge progress will appear here once you are rostered.</span></div>`;}const items=teamChallengeItems();if(items.length&&!items.some(x=>String(x.challenge.id)===String(activeTeamChallengeId)))activeTeamChallengeId=String(items[0].challenge.id);const selected=items.find(x=>String(x.challenge.id)===String(activeTeamChallengeId))||items[0];const roster=(gamesState.myTeam.members||[]).map(m=>`<span class="games-team-member-chip">${esc(m.name||m.rsn||m.displayName||m.discordName||m.discordId||"Member")}</span>`).join("");return `<section class="team-hub"><header class="team-hub-header"><div><p class="eyebrow">YOUR TEAM · ${esc(currentWeek()?.name||"CURRENT WEEK")}</p><h1>${esc(gamesState.myTeam.name)}</h1><p>Your team's private challenge workspace. Track assignments, progress and side challenges in one place.</p></div><div class="team-hub-roster"><span>ROSTER · ${Number(gamesState.myTeam.memberCount)||0}</span><div>${roster||`<span class="games-muted">Roster unavailable</span>`}</div></div></header>${items.length?`<nav class="team-hub-tabs" aria-label="Your team challenge trackers">${items.map((x,i)=>`<button type="button" class="${String(x.challenge.id)===String(selected?.challenge.id)?"is-active":""}" data-team-challenge-tab="${esc(x.challenge.id)}"><span>${x.type==="contracts"?"◆":x.type==="shopping"?"▦":x.type==="locations"?"⌖":x.type==="trivia"?"?":x.type==="trials"?"⏱":"◇"}</span>${esc(x.challenge.name||`Challenge ${i+1}`)}</button>`).join("")}</nav>`:""}<div class="team-hub-content">${renderTeamChallengePanel(selected)}</div></section>`;}
async function loadTeamCluePanel(el,force=false){const [weekId,challengeId]=el.dataset.teamClueProgress.split("|");try{if(gamesState.testMode){el.innerHTML=`<div class="team-hub-empty"><strong>Clue tracking uses the live roster.</strong><span>Contracts support isolated Test Mode now. Side-challenge test data will be added with the new side challenges.</span></div>`;return;}const q=new URLSearchParams({weekId,challengeId});if(force)q.set("refresh","1");const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);let r;try{r=await fetch(`/api/ironkin-games/clue-progress?${q}`,{cache:"no-store",signal:controller.signal});}finally{clearTimeout(timeout);}const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||"Could not load clue progress.");const tiers=["beginner","easy","medium","hard","elite","master"],labels={beginner:"Beginner",easy:"Easy",medium:"Medium",hard:"Hard",elite:"Elite",master:"Master"};const rows=(d.rows||[]).map(row=>`<tr><td class="player-cell"><strong>${esc(row.name||row.rsn)}</strong>${row.name&&row.rsn&&row.name!==row.rsn?`<small>${esc(row.rsn)}</small>`:""}</td>${tiers.map(t=>`<td>${Number(row.tiers?.[t])||0}</td>`).join("")}<td class="total-cell">${Number(row.clues)||0}</td><td class="points-cell">${Number(row.points)||0}</td></tr>`).join("");const remaining=Math.max(0,Number(d.refreshAvailableAt||0)-Date.now()),mins=Math.max(1,Math.ceil(remaining/60000));el.innerHTML=`<div class="clue-summary team-clue-summary"><div><span>TEAM POINTS</span><strong>${Number(d.totals?.points||0).toLocaleString()}</strong></div><div><span>TOTAL CLUES</span><strong>${Number(d.totals?.clues)||0}</strong></div><div><span>LAST UPDATED</span><strong>${d.updatedAt?fmtDate(d.updatedAt):"Just now"}</strong></div><button class="games-btn secondary" type="button" data-team-clue-refresh ${remaining>0?"disabled":""}>${remaining>0?`Refresh in ${mins}m`:"Refresh WOM"}</button></div><section class="clue-table-card"><div class="clue-table-wrap"><table><thead><tr><th>Teammate</th>${tiers.map(t=>`<th>${labels[t]}</th>`).join("")}<th>Total</th><th>Points</th></tr></thead><tbody>${rows||`<tr><td colspan="9">No rostered players found.</td></tr>`}</tbody></table></div><div class="clue-key"><span><b>0.5</b> Beginner</span><span><b>1</b> Easy</span><span><b>2</b> Medium</span><span><b>4</b> Hard</span><span><b>7</b> Elite</span><span><b>10</b> Master</span></div></section>`;const b=el.querySelector("[data-team-clue-refresh]");if(b&&!b.disabled)b.onclick=()=>loadTeamCluePanel(el,true);}catch(e){const msg=e?.name==="AbortError"?"Wise Old Man took too long to respond. Try refreshing the clue tracker.":e.message;el.innerHTML=`<div class="games-participant-warning"><strong>Clue progress unavailable</strong><span>${esc(msg)}</span><button class="games-btn secondary" type="button" data-team-clue-retry>Try Again</button></div>`;const retry=el.querySelector("[data-team-clue-retry]");if(retry)retry.onclick=()=>loadTeamCluePanel(el,true);}}
async function loadShoppingListPanel(el){
  const [weekId,challengeId]=el.dataset.teamShoppingList.split("|");
  try{
    const q=new URLSearchParams({weekId,challengeId});
    const selectedAdminTeam=el.dataset.adminTeamId||"";
    if(selectedAdminTeam)q.set("adminTeamId",selectedAdminTeam);
    if(gamesState.testMode){q.set("test","1");q.set("testTeamId",gamesState.myTeam?.id||"");}
    const r=await fetch(`/api/ironkin-games/shopping-list?${q}`,{cache:"no-store"}),d=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error(d.error||"Could not load Shopping List.");
    el.dataset.adminTeamId=d.teamId||selectedAdminTeam;
    const teamPicker=d.isStaff&&Array.isArray(d.teams)&&d.teams.length?`<div class="shopping-admin-team"><label>ADMIN TEAM</label><select data-shopping-team>${d.teams.map(t=>`<option value="${esc(t.id)}" ${String(t.id)===String(d.teamId)?"selected":""}>${esc(t.name)}</option>`).join("")}</select><span>Add or correct drops for any team without switching your own team.</span></div>`:"";
    const cards=(d.items||[]).map(item=>{
      const displayItemId=Number(item.matchedItemId)||Number(item.itemId)||0,icon=item.image||`https://static.runelite.net/cache/item/icon/${displayItemId}.png`,approved=item.status==="approved",pending=item.status==="pending";
      const admin=!approved&&!pending&&d.isStaff?`<div class="shopping-admin-mark"><select data-shopping-member><option value="">Select player…</option>${(d.teamMembers||[]).map(m=>`<option value="${esc(m.discordId)}">${esc(m.name)}</option>`).join("")}</select><button type="button" class="games-btn secondary compact" data-shopping-mark="${esc(item.id)}">Mark Found</button></div>`:"";
      return `<article class="shopping-item ${approved?"is-found":pending?"is-pending":"is-missing"}"><div class="shopping-item-icon"><img src="${esc(icon)}" alt="" loading="lazy"></div><div class="shopping-item-copy"><strong>${esc(item.name)}</strong><span>${approved?`✓ Found by ${esc(item.playerName||"Team member")}`:pending?`Proof pending · ${esc(item.playerName||"Team member")}`:"Still needed"}</span>${item.obtainedAt?`<small>${fmtDate(item.obtainedAt)}</small>`:""}${admin}</div>${approved?`<span class="shopping-status found">FOUND</span>`:pending?`<span class="shopping-status pending">PENDING</span>`:`<span class="shopping-status needed">NEEDED</span>`}</article>`;
    }).join("");
    el.innerHTML=`${teamPicker}<div class="shopping-summary"><div><span>FOUND</span><strong>${Number(d.found)||0}<small>/ ${Number(d.total)||0}</small></strong></div><div><span>PROOF PENDING</span><strong>${Number(d.pending)||0}</strong></div><div><span>REMAINING</span><strong>${Math.max(0,(Number(d.total)||0)-(Number(d.found)||0)-(Number(d.pending)||0))}</strong></div><div class="shopping-summary-note">Once an item is submitted for your team, RuneLite stops tracking that Shopping List item unless the proof is rejected.</div></div><div class="shopping-item-grid">${cards||`<div class="team-hub-empty"><strong>No Shopping List items configured.</strong></div>`}</div>`;
    const teamSelect=el.querySelector("[data-shopping-team]");
    if(teamSelect)teamSelect.onchange=async()=>{el.dataset.adminTeamId=teamSelect.value;await loadShoppingListPanel(el);};
    el.querySelectorAll("[data-shopping-mark]").forEach(btn=>btn.onclick=async()=>{
      const select=btn.closest(".shopping-admin-mark")?.querySelector("[data-shopping-member]");
      if(!select?.value){alert("Select the team member who obtained this item.");return;}
      if(!confirm("Mark this Shopping List item as found for the selected player?"))return;
      btn.disabled=true;
      const rr=await fetch("/api/ironkin-games/shopping-list",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({weekId,challengeId,teamId:d.teamId,objectiveId:btn.dataset.shoppingMark,discordId:select.value})});
      const dd=await rr.json().catch(()=>({}));
      if(!rr.ok){alert(dd.error||"Could not mark item found.");btn.disabled=false;return;}
      await loadShoppingListPanel(el);
    });
  }catch(e){el.innerHTML=`<div class="games-participant-warning"><strong>Shopping List unavailable</strong><span>${esc(e.message)}</span></div>`;}
}
function bindLocationForms(root){root.querySelectorAll("[data-location-submit]").forEach(form=>form.onsubmit=async ev=>{ev.preventDefault();const [weekId,challengeId,locationId]=form.dataset.locationSubmit.split("|"),btn=form.querySelector("button"),msg=form.querySelector("small"),fd=new FormData(form);fd.set("weekId",weekId);fd.set("challengeId",challengeId);fd.set("locationId",locationId);btn.disabled=true;btn.textContent="Uploading…";try{const r=await fetch("/api/ironkin-games/location-hunt",{method:"POST",body:fd}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||"Submission failed.");await loadLocationHuntPanel(root.closest("[data-team-location-hunt]")||root);}catch(e){msg.textContent=e.message;btn.disabled=false;btn.textContent="Submit Proof";}});}
async function loadTriviaHuntPanel(el){const [weekId,challengeId]=el.dataset.teamTriviaHunt.split("|");try{const q=new URLSearchParams({weekId,challengeId});if(gamesState.testMode){q.set("test","1");q.set("testTeamId",gamesState.myTeam?.id||"");}else if(el.dataset.triviaAdminTeamId){q.set("adminTeamId",el.dataset.triviaAdminTeamId);}const r=await fetch(`/api/ironkin-games/trivia-hunt?${q}`,{cache:"no-store"}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||"Could not load Trivia Hunt.");const cards=(d.hunts||[]).map((x,i)=>{const locked=!x.revealed&&!x.adminPreview,approved=x.status==="approved",attempts=Array.isArray(x.attempts)?x.attempts:[];const attemptsHtml=attempts.length?`<div class="trivia-attempts"><strong>Your Team's Submissions <span>${attempts.length}</span></strong>${attempts.slice().reverse().map(a=>`<div class="trivia-attempt-row"><a href="${esc(a.proofUrl)}" target="_blank" rel="noopener">View proof</a><span>${esc(a.submittedBy)} · ${fmtDate(a.submittedAt)}</span><b class="trivia-status trivia-status-${esc(String(a.status||"pending").toLowerCase())}">${esc(String(a.status||"pending").toUpperCase())}</b>${a.staffNote?`<small>${esc(a.staffNote)}</small>`:""}</div>`).join("")}</div>`:"";const answer=x.adminPreview&&x.answer?`<div class="trivia-admin-answer"><span>ADMIN ANSWER</span><strong>${esc(x.answer)}</strong></div>`:"";return `<article class="location-card trivia-card ${locked?"is-locked":approved?"is-approved":""}"><div class="location-card-head"><span>DAY ${i+1}</span><strong>${locked?"Trivia Sealed":esc(x.title||`Trivia ${i+1}`)}</strong><em>${x.adminPreview?"ADMIN PREVIEW · SEALED":gamesState.testMode?"TEST REALM":locked?`REVEALS ${fmtDate(x.revealsAt)}`:approved?"COMPLETED":"AVAILABLE"}</em></div>${locked?`<div class="location-locked"><b>?</b><strong>TRIVIA SEALED</strong><span>Reveals ${fmtDate(x.revealsAt)}</span><small>The clue stays sealed until reveal.</small></div>`:`<div class="trivia-reveal"><div class="trivia-section"><span>CLUE</span><p>${esc(x.clue)}</p></div>${answer}<div class="trivia-section trivia-proof-required"><span>PROOF REQUIRED</span><p>${esc(x.requirement)}</p></div></div>${attemptsHtml}${x.revealed&&!d.isClosed?`<form class="location-submit" data-trivia-submit="${esc(weekId)}|${esc(challengeId)}|${esc(x.id)}"><label><span>Proof screenshot</span><input name="proof" type="file" accept="image/png,image/jpeg,image/webp" required></label><button class="games-btn" type="submit">Upload Proof</button><small>Unlimited attempts. Each upload keeps its original server-recorded submission time.</small></form>`:""}`}</article>`;}).join("");const staffReview=Array.isArray(d.staffReview)?d.staffReview:[];const huntById=new Map((d.hunts||[]).map(h=>[String(h.id),h]));const teams=Array.isArray(d.teams)?d.teams:[];const dayTabs=(d.hunts||[]).map((h,i)=>{const rows=staffReview.filter(x=>String(x.huntId)===String(h.id)),pending=rows.filter(x=>x.status==="pending").length;return `<button type="button" class="trivia-review-tab ${i===0?"is-active":""}" data-trivia-review-day="${esc(String(h.id))}">Day ${i+1}<span>${rows.length}${pending?` · ${pending} pending`:""}</span></button>`}).join("");const teamTabs=(d.hunts||[]).map((h,di)=>`<div class="trivia-review-team-tabs ${di===0?"is-active":""}" data-trivia-review-team-tabs="${esc(String(h.id))}">${teams.map((t,ti)=>{const rows=staffReview.filter(x=>String(x.huntId)===String(h.id)&&String(x.teamId)===String(t.id)),pending=rows.filter(x=>x.status==="pending").length;return `<button type="button" class="trivia-review-tab trivia-review-team-tab ${ti===0?"is-active":""}" data-trivia-review-team="${esc(String(h.id))}|${esc(String(t.id))}">${esc(t.name)}<span>${rows.length}${pending?` · ${pending} pending`:""}</span></button>`}).join("")}</div>`).join("");const reviewPanels=(d.hunts||[]).map((h,di)=>teams.map((t,ti)=>{const rows=staffReview.filter(x=>String(x.huntId)===String(h.id)&&String(x.teamId)===String(t.id));return `<div class="trivia-review-panel ${di===0&&ti===0?"is-active":""}" data-trivia-review-panel="${esc(String(h.id))}|${esc(String(t.id))}">${rows.length?`<div class="location-review-grid">${rows.map(x=>`<article class="location-review-card"><img src="${esc(x.proofUrl)}" alt="Trivia proof"><div><span>${d.testMode?"TEST REALM · ":"LIVE · "}${esc(x.teamName)}</span><strong>Day ${di+1} · ${esc(h.title||`Trivia ${di+1}`)}</strong><small>Submitted ${fmtDate(x.submittedAt)} by ${esc(x.submittedBy||"Team member")} · ${esc(String(x.status||"pending").toUpperCase())}</small>${x.staffNote?`<small>${esc(x.staffNote)}</small>`:""}${x.status==="pending"?`<textarea data-trivia-admin-note="${esc(x.id)}" rows="2" placeholder="Staff note (optional)"></textarea><div class="games-record-actions"><button class="games-btn" type="button" data-trivia-admin-review="${esc(x.id)}|approved">Approve</button><button class="games-btn danger" type="button" data-trivia-admin-review="${esc(x.id)}|rejected">Reject</button></div>`:""}</div></article>`).join("")}</div>`:`<div class="games-empty-state">No submissions for ${esc(t.name)} on Day ${di+1}.</div>`}</div>`}).join("")).join("");const adminTeamPicker=d.isStaff?`<div class="games-card" style="margin-bottom:14px;padding:16px"><label style="display:block;margin-bottom:8px;font-weight:700">Upload proof for team</label><select data-trivia-admin-team-select style="width:100%;max-width:360px;padding:10px;background:#15110e;color:#fff;border:1px solid #6e4a24;border-radius:8px">${teams.map(t=>`<option value="${esc(t.id)}" ${String(t.id)===String(d.teamId)?"selected":""}>${esc(t.name)}</option>`).join("")}</select><p class="games-muted" style="margin-top:8px">The Day 1–5 upload forms and submission history below belong to the selected team. Changing teams will not move existing proofs.</p></div>`:"";const adminReview=d.isStaff?`<section class="games-card trivia-review-card" style="margin-bottom:14px"><div class="games-card-heading"><div><p class="eyebrow">${d.testMode?"TEST REALM":"LIVE"} · ADMIN</p><h3>Trivia Proof Review</h3><p class="games-muted">Choose a day, then a team. Approval keeps the original server-recorded upload time for placement.</p></div><span class="games-count-pill">${staffReview.filter(x=>x.status==="pending").length} pending</span></div><div class="trivia-review-tabs">${dayTabs}</div>${teamTabs}<div class="trivia-review-panels">${reviewPanels}</div></section>`:"";el.innerHTML=`${gamesState.testMode?`<div class="games-participant-warning"><strong>TEST REALM · Trivia submissions enabled</strong><span>Uploads and approvals here are isolated from the live challenge and do not affect live scores.</span></div>`:""}${adminReview}${adminTeamPicker}<div class="location-summary"><div><span>COMPLETED</span><strong>${Number(d.approved)||0}<small>/ ${Number(d.total)||0}</small></strong></div><div><span>TEAM BONUS</span><strong>${Number(d.points)||0}<small> pts</small></strong></div><p>Unlimited team attempts. Placement uses the earliest approved proof's original server-recorded upload time. 1st 5 · 2nd 3 · 3rd 2 · 4th 1.</p></div><div class="location-grid">${cards}</div>`;el.querySelector("[data-trivia-admin-team-select]")?.addEventListener("change",ev=>{el.dataset.triviaAdminTeamId=ev.target.value;loadTriviaHuntPanel(el);});el.querySelectorAll("[data-trivia-review-day]").forEach(btn=>btn.onclick=()=>{const day=btn.dataset.triviaReviewDay;el.querySelectorAll("[data-trivia-review-day]").forEach(x=>x.classList.toggle("is-active",x===btn));el.querySelectorAll("[data-trivia-review-team-tabs]").forEach(x=>x.classList.toggle("is-active",x.dataset.triviaReviewTeamTabs===day));const teamBtn=el.querySelector(`[data-trivia-review-team^="${CSS.escape(day)}|"]`);if(teamBtn)teamBtn.click();});el.querySelectorAll("[data-trivia-review-team]").forEach(btn=>btn.onclick=()=>{const key=btn.dataset.triviaReviewTeam,[day]=key.split("|");el.querySelectorAll(`[data-trivia-review-team^="${CSS.escape(day)}|"]`).forEach(x=>x.classList.toggle("is-active",x===btn));el.querySelectorAll("[data-trivia-review-panel]").forEach(x=>x.classList.toggle("is-active",x.dataset.triviaReviewPanel===key));});el.querySelectorAll("[data-trivia-admin-review]").forEach(btn=>btn.onclick=async()=>{const[id,status]=btn.dataset.triviaAdminReview.split("|"),note=el.querySelector(`[data-trivia-admin-note="${CSS.escape(id)}"]`)?.value||"";btn.disabled=true;try{const rr=await fetch("/api/admin/ironkin-games/location-hunt-review",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id,status,staffNote:note})}),dd=await rr.json().catch(()=>({}));if(!rr.ok)throw new Error(dd.error||"Review failed.");await loadTriviaHuntPanel(el);}catch(err){btn.disabled=false;alert(err.message);}});el.querySelectorAll("[data-trivia-submit]").forEach(form=>form.onsubmit=async ev=>{ev.preventDefault();const [w,c,h]=form.dataset.triviaSubmit.split("|"),fd=new FormData(form),btn=form.querySelector("button"),msg=form.querySelector("small");fd.set("weekId",w);fd.set("challengeId",c);fd.set("huntId",h);if(d.isStaff&&!gamesState.testMode)fd.set("adminTeamId",d.teamId);if(gamesState.testMode){fd.set("test","1");fd.set("testTeamId",gamesState.myTeam?.id||"");}btn.disabled=true;btn.textContent="Uploading…";try{const rr=await fetch("/api/ironkin-games/trivia-hunt",{method:"POST",body:fd}),dd=await rr.json().catch(()=>({}));if(!rr.ok)throw new Error(dd.error||"Submission failed.");await loadTriviaHuntPanel(el);}catch(err){msg.textContent=err.message;btn.disabled=false;btn.textContent="Upload Proof";}});}catch(e){el.innerHTML=`<div class="games-participant-warning"><strong>Trivia Hunt unavailable</strong><span>${esc(e.message)}</span></div>`;}}
function hydrateTeamPanels(){document.querySelectorAll("[data-team-clue-progress]").forEach(el=>loadTeamCluePanel(el));document.querySelectorAll("[data-team-shopping-list]").forEach(el=>loadShoppingListPanel(el));document.querySelectorAll("[data-team-location-hunt]").forEach(el=>loadLocationHuntPanel(el));document.querySelectorAll("[data-team-trivia-hunt]").forEach(el=>loadTriviaHuntPanel(el));}
function renderSchedule(){const rows=[];const sessions=gamesState.scheduleSessions||[];(gamesState.weeks||[]).forEach(w=>(w.challenges||[]).forEach(c=>{const kind=(c.kind||"main").toLowerCase()==="side"?"Side Challenge":"Main Challenge";sessions.filter(s=>s.weekId===w.id&&s.challengeId===c.id).forEach(s=>{const team=gamesState.teams.find(t=>t.id===s.teamId);const st=deriveScheduleStatus(s);rows.push({week:w.name,kind,team:team?.name||"Team",opens:c.opensAt,closes:c.closesAt,booked:s.scheduledAt,status:st.label,statusKey:st.key});});}));rows.sort((a,b)=>new Date(a.booked||0)-new Date(b.booked||0));const body=rows.map(r=>`<div class="schedule-row schedule-row-master"><strong data-label="Challenge">${esc(r.week)} · ${esc(r.kind)}</strong><strong data-label="Team">${esc(r.team)}</strong><span data-label="Opens">${r.opens?fmtDate(r.opens):"—"}</span><span data-label="Closes">${r.closes?fmtDate(r.closes):"—"}</span><span data-label="Booked Time" class="schedule-booked-time">${r.booked?fmtDate(r.booked):"Not booked"}</span><span data-label="Status"><span class="games-pill schedule-status challenge-status-${esc(r.statusKey)}">${esc(r.status)}</span></span></div>`).join("");return `<div class="games-card full"><h2>Master Schedule</h2><p class="games-muted schedule-help">All team bookings are shown here. Status updates automatically from Booked → In Progress → Completed → Submitted/Approved. Challenges are identified only as Main Challenge or Side Challenge so hidden challenge details are never revealed.</p>${rows.length?`<div class="schedule-table schedule-table-master"><div class="schedule-header schedule-header-master"><span>Challenge</span><span>Team</span><span>Opens</span><span>Closes</span><span>Booked Time</span><span>Status</span></div>${body}</div>`:"No team bookings yet."}</div>`;}
function resultPlaceLabel(place){const n=Number(place)||0;return n===1?"1st":n===2?"2nd":n===3?"3rd":n?`${n}th`:"—";}
function resultBreakdownHtml(challenge,row){const b=row?.autoBreakdown||row?.breakdown||{},tracker=String(challenge?.trackerType||challenge?.trackingMode||"").toLowerCase();
  if(tracker==="wom-clues"||tracker==="clue-progress"){const tiers=[["beginner","Beginner"],["easy","Easy"],["medium","Medium"],["hard","Hard"],["elite","Elite"],["master","Master"]],total=tiers.reduce((n,[k])=>n+(Number(b[k])||0),0);return `<div class="result-stat-strip"><span><b>${total}</b>Total clues</span>${tiers.map(([k,l])=>`<span><b>${Number(b[k])||0}</b>${l}</span>`).join("")}</div>`;}
  if(tracker==="timed-wom-attempt"||tracker==="boss-rush"){const bosses=Array.isArray(b.uniqueBosses)?b.uniqueBosses:[],missed=Array.isArray(b.missedBosses)?b.missedBosses:[],total=Number(b.totalBosses)||71,completed=Number(b.attemptsCompleted)||0,expected=Number(b.attemptsExpected)||0;return `<div class="result-stat-strip"><span><b>${bosses.length} / ${total}</b>Unique bosses</span><span><b>${missed.length}</b>Bosses not killed</span><span><b>${completed}${expected?` / ${expected}`:""}</b>Attempts completed</span></div>${bosses.length?`<details class="result-detail"><summary>View ${bosses.length} completed bosses</summary><div class="result-chip-list">${bosses.map(x=>`<span>${esc(String(x).replace(/_/g," "))}</span>`).join("")}</div></details>`:""}${missed.length?`<details class="result-detail"><summary>View ${missed.length} bosses not killed</summary><div class="result-chip-list">${missed.map(x=>`<span>${esc(x.label||String(x.metric||x).replace(/_/g," "))}</span>`).join("")}</div></details>`:""}`;}
  if(tracker==="shopping-list"){const items=Array.isArray(b.items)?b.items:[];return `<div class="result-stat-strip"><span><b>${Number(b.found)||items.length}</b>Items found</span><span><b>${Number(b.total)||0}</b>List size</span></div>${items.length?`<details class="result-detail"><summary>View collected items</summary><div class="result-detail-list">${items.map(x=>`<div><strong>${esc(x.name||"Item")}</strong><span>${x.player?`Found by ${esc(x.player)}`:"Team find"}${x.obtainedAt?` · ${fmtDate(x.obtainedAt)}`:""}</span></div>`).join("")}</div></details>`:""}`;}
  if(tracker==="contracts"){const contracts=Array.isArray(b.contracts)?b.contracts:[];return `<div class="result-stat-strip"><span><b>${Number(b.completed)||contracts.filter(x=>x.completed).length}</b>Completed</span><span><b>${Number(b.claimed)||contracts.length}</b>Claimed</span></div>${contracts.length?`<details class="result-detail"><summary>View team contracts</summary><div class="result-detail-list">${contracts.map(x=>`<div><strong>${esc(x.name||"Contract")}</strong><span>${esc(titleCaseStatus(x.tier||""))}${x.player?` · ${esc(x.player)}`:""} · ${x.completed?"Completed":"Incomplete"}</span></div>`).join("")}</div></details>`:""}`;}
  if(tracker==="location-hunt"){const locs=Array.isArray(b.locations)?b.locations:[];return `<div class="result-stat-strip"><span><b>${Number(b.approved)||locs.length}</b>Locations completed</span><span><b>${Number(b.total)||0}</b>Total locations</span></div>${locs.length?`<details class="result-detail"><summary>View completed locations</summary><div class="result-detail-list">${locs.map(x=>`<div><strong>${esc(x.title||"Location")}</strong><span>${x.submittedAt?`Submitted ${fmtDate(x.submittedAt)}`:"Completed"}</span></div>`).join("")}</div></details>`:""}`;}
  if(b.metric)return `<div class="result-stat-strip"><span><b>${Number(row?.scoreValue)||0}</b>${esc(b.metric)}</span></div>`;
  return row?.notes&&row.notes!=="Automatically calculated from the challenge tracker."?`<p class="result-team-note">${esc(row.notes)}</p>`:"";
}
function challengeResultsHtml(week,challenge,submissions,{preview=false}={}){const teams=gamesState?.teams||[],rows=teams.map(team=>{const row=submissions.find(s=>String(s.teamId)===String(team.id));return row?{...row,teamName:team.name}:null}).filter(Boolean).sort((a,b)=>(Number(a.placement)||99)-(Number(b.placement)||99)||(Number(b.points)||0)-(Number(a.points)||0)||String(a.teamName).localeCompare(String(b.teamName)));if(!rows.length)return "";const tracker=String(challenge.trackerType||challenge.trackingMode||"").toLowerCase(),label=tracker==="wom-clues"||tracker==="clue-progress"?"CLUE HUNTERS":tracker==="timed-wom-attempt"||tracker==="boss-rush"?"BOSS RUSH":tracker==="shopping-list"?"SHOPPING LIST":tracker==="contracts"?"CONTRACTS":tracker==="location-hunt"?"LOCATION HUNT":"CHALLENGE RESULTS";return `<section class="results-challenge-card"><header class="results-challenge-head"><div><p class="eyebrow">${esc((challenge.kind||"main").toUpperCase())} · ${label}</p><h3>${esc(challenge.name||"Challenge")}</h3></div>${preview?`<span class="games-pill challenge-status-booked">TEST PREVIEW</span>`:""}</header><div class="results-team-grid">${rows.map(r=>`<article class="result-team-card place-${Number(r.placement)||0}"><div class="result-team-top"><span class="result-place">${resultPlaceLabel(r.placement)}</span><div><strong>${esc(r.teamName||"Team")}</strong><small>${esc(r.score||r.scoreLabel||"Result recorded")}</small></div><b>+${Number(r.points)||0}<small> pts</small></b></div>${resultBreakdownHtml(challenge,r)}</article>`).join("")}</div></section>`;}
function publishedWeekResultsHtml(week){const approved=(gamesState.submissions||[]).filter(s=>String(s.weekId)===String(week.id)&&String(s.status||"").toLowerCase()==="approved");return (week.challenges||[]).map(c=>challengeResultsHtml(week,c,approved.filter(s=>String(s.challengeId)===String(c.id)))).filter(Boolean).join("");}
async function hydrateTestResultsPreviews(){if(!gamesState?.testMode||!gamesState?.isStaff)return;for(const el of document.querySelectorAll("[data-test-results-preview]")){const weekId=el.dataset.testResultsPreview;try{const r=await fetch("/api/admin/ironkin-games/publish-results",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({weekId,action:"preview"})}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||"Could not calculate preview.");const week=(gamesState.weeks||[]).find(w=>String(w.id)===String(weekId));const html=(d.challenges||[]).map(result=>{const c=(week?.challenges||[]).find(x=>String(x.id)===String(result.challengeId))||{id:result.challengeId,name:result.name,kind:result.kind,trackerType:result.tracker};const rows=(result.rows||[]).map(x=>({...x,score:x.scoreLabel,scoreValue:x.score,autoBreakdown:x.breakdown,status:"approved"}));return challengeResultsHtml(week,c,rows,{preview:true});}).join("");el.innerHTML=html||`<div class="results-preview-empty"><strong>No automatic results to preview.</strong><span>Manual reviewed results will appear here after publication.</span></div>`;}catch(e){el.innerHTML=`<div class="games-participant-warning"><strong>Test results preview unavailable</strong><span>${esc(e.message)}</span></div>`;}}}
function renderResults(){
  const weeks=gamesState?.weeks||[];
  const allPublished=weeks.length>0&&weeks.every(w=>isWeekPublished(w.id));
  const endControl=gamesState.isStaff&&!gamesState.gamesCompleted?`<article class="games-card full games-end-games-card"><p class="eyebrow">Event Finalization</p><h2>${gamesState.canEndGames?"Ready to Crown the Champion":"End Ironkin Games"}</h2><p>${gamesState.canEndGames?"Every configured week is published and every submitted result has been reviewed. Finalize the event to lock the standings and declare the champion.":"Publish every week and review all pending submissions before the Games can be finalized."}</p><button class="games-btn games-end-games-btn" type="button" data-end-games ${gamesState.canEndGames?"":"disabled"}>🏆 End Ironkin Games</button></article>`:"";
  const finalHeader=gamesState.gamesCompleted?`<article class="games-card full games-results-final"><p class="eyebrow">🏆 FINAL RESULTS</p><h2>${esc(championNames())} — ${(gamesState.winnerTeamIds||[]).length>1?"Co-Champions":"Ironkin Games Champions"}</h2><p>Finalized ${fmtDate(gamesState.completedAt)}. These standings are locked.</p>${finalStandingsHtml()}</article>`:`<article class="games-card full results-center-hero"><div><p class="eyebrow">Official Scoring</p><h2>${gamesState.testMode?"Results Center · Test Mode":allPublished?"All Weeks Published":"Results Center"}</h2><p>${gamesState.testMode?"Private staff preview. Automatic results below are calculated live and do not publish or change standings.":"Published weeks remain visible here for the rest of the event. Open each team result to see exactly what they completed."}</p></div>${gamesState.testMode?`<span class="results-test-badge">🧪 PRIVATE PREVIEW</span>`:""}</article>`;
  const weekCards=weeks.map((week,index)=>{const published=isWeekPublished(week.id),weekSubs=(gamesState.submissions||[]).filter(s=>String(s.weekId)===String(week.id));let controls="";if(gamesState.isStaff&&!gamesState.gamesCompleted)controls=published?`<button class="games-btn secondary" type="button" data-publish-results="hide" data-week-id="${esc(week.id)}">Hide Public Results</button>`:`<button class="games-btn" type="button" data-publish-results="publish" data-week-id="${esc(week.id)}">Preview & Publish</button>`;const detailed=published?publishedWeekResultsHtml(week):"";const testPreview=gamesState.testMode&&gamesState.isStaff&&!published?`<div class="results-test-preview" data-test-results-preview="${esc(week.id)}"><div class="games-contract-loading">Calculating private test results…</div></div>`:"";return `<article class="games-card full games-results-week ${published?"is-published":"is-locked"}"><div class="games-card-heading results-week-heading"><div><p class="eyebrow">Week ${index+1}</p><h2>${esc(week.name||`Week ${index+1}`)}</h2><p class="games-muted">${published?"Official team results and challenge breakdowns.":gamesState.testMode?"Private test-mode calculation — nothing below is public.":"Results stay sealed until staff publishes this week."}</p></div><span class="games-pill ${published?"challenge-status-approved":"challenge-status-booked"}">${published?"Published":gamesState.testMode?"Test Preview":"Results Locked"}</span></div>${published?(detailed||`<div class="results-preview-empty"><strong>No approved results were recorded.</strong></div>`):testPreview||(gamesState.isStaff?`<p class="games-muted">Staff view: ${weekSubs.length} submission(s) recorded. Use Preview & Publish to calculate automatic placements.</p>`:"")}${controls?`<div class="challenge-actions results-publish-actions">${controls}</div>`:""}</article>`;}).join("");
  const draftArchive=gamesState.draftStatus==="complete"?`<div class="games-draft-results-link"><a class="games-btn secondary" href="/ironkin-games-draft.html">View Draft Results</a></div>`:"";
  return `<div class="games-grid">${finalHeader}${draftArchive}${weekCards||`<article class="games-card full">No weeks have been configured yet.</article>`}${endControl}</div>`;
}
function openChallengeDetails(data){document.querySelector(".games-challenge-modal")?.remove();const rules=Array.isArray(data.rules)?data.rules:[];const modal=document.createElement("div");modal.className="games-challenge-modal";modal.innerHTML=`<div class="games-challenge-modal-backdrop" data-challenge-close></div><section class="games-challenge-modal-panel" role="dialog" aria-modal="true" aria-label="${esc(data.name||"Challenge")} details"><header><div><span>${esc(data.label||"CHALLENGE")}</span><h2>${esc(data.name||"Challenge")}</h2></div><button type="button" class="games-challenge-modal-close" data-challenge-close aria-label="Close">×</button></header><div class="games-challenge-modal-body">${data.summary?`<p class="challenge-modal-summary">${esc(data.summary)}</p>`:""}<div class="challenge-modal-meta"><span>◷ ${esc(data.open?fmtDate(data.open):"TBD")} → ${esc(data.close?fmtDate(data.close):"TBD")}</span><span>♟ ${esc(data.participants||"Team-selected")}</span><span>✓ ${esc(data.tracking||"Proof required")}</span></div>${data.brief?`<section class="challenge-modal-section"><h3>Challenge brief</h3><p>${esc(data.brief)}</p></section>`:""}${rules.length?`<section class="challenge-modal-section"><div class="challenge-modal-section-head"><h3>Rules & scoring</h3><span>${rules.length} rules</span></div><div class="games-rules-modal-grid">${rules.map((r,i)=>`<div class="games-rule-item"><span>${i+1}</span><p>${esc(r)}</p></div>`).join("")}</div></section>`:""}</div></section>`;document.body.appendChild(modal);document.body.classList.add("games-modal-open");const close=()=>{modal.remove();document.body.classList.remove("games-modal-open");document.removeEventListener("keydown",key)};const key=e=>{if(e.key==="Escape")close()};modal.querySelectorAll("[data-challenge-close]").forEach(x=>x.addEventListener("click",close));document.addEventListener("keydown",key);modal.querySelector(".games-challenge-modal-close")?.focus();}
function openChallengeRules(title,rules){document.querySelector(".games-rules-modal")?.remove();const modal=document.createElement("div");modal.className="games-rules-modal";modal.innerHTML=`<div class="games-rules-modal-backdrop" data-rules-close></div><section class="games-rules-modal-panel" role="dialog" aria-modal="true" aria-label="${esc(title)} rules and scoring"><header><div><span>RULES & SCORING</span><h2>${esc(title)}</h2></div><button type="button" class="games-rules-modal-close" data-rules-close aria-label="Close">×</button></header><div class="games-rules-modal-grid">${rules.map((r,i)=>`<div class="games-rule-item"><span>${i+1}</span><p>${esc(r)}</p></div>`).join("")}</div></section>`;document.body.appendChild(modal);document.body.classList.add("games-modal-open");const close=()=>{modal.remove();document.body.classList.remove("games-modal-open");document.removeEventListener("keydown",key)};const key=e=>{if(e.key==="Escape")close()};modal.querySelectorAll("[data-rules-close]").forEach(x=>x.addEventListener("click",close));document.addEventListener("keydown",key);modal.querySelector(".games-rules-modal-close")?.focus();}
function renderRules(){return `<div class="games-grid"><article class="games-card full"><h2>Competition Integrity</h2><ol>${(gamesState.rules||[]).map(r=>`<li>${esc(r)}</li>`).join("")}</ol><p><strong>Main Challenge:</strong> ${gamesState.scoring?.main?.join(" / ")||"100 / 75 / 55 / 40"} points by placement.</p><p><strong>Side Challenge:</strong> ${gamesState.scoring?.side?.join(" / ")||"30 / 20 / 15 / 10"} points by placement.</p></article></div>`;}
function renderTeamBanner(){const el=$("gamesTeamBanner");if(!el)return;if(gamesState.myTeam){el.hidden=false;el.innerHTML=`<div><span class="games-team-banner-label">${gamesState.testMode?"🧪 STAFF TEST MODE":"YOUR IRONKIN GAMES TEAM"}</span><strong>${esc(gamesState.myTeam.name)}</strong>${gamesState.testMode?`<small>Private preview · test claims never count toward live results</small>`:""}</div><span class="games-team-banner-count">${Number(gamesState.myTeam.memberCount)||0} members</span>`;}else if(gamesState.signedIn){el.hidden=false;el.innerHTML=`<div><span class="games-team-banner-label">IRONKIN GAMES TEAM</span><strong>Not assigned to a team yet</strong></div>`;}else{el.hidden=true;el.innerHTML="";}}
function render(){
  if(!gamesState)return;
  $("gamesTitle").textContent=gamesState.title||"Ironkin Games";
  $("gamesSubtitle").textContent=gamesState.subtitle||"";
  const hidden=!gamesState.enabled&&!gamesState.isStaff;
  const full=Boolean(gamesState.access?.full||gamesState.isStaff);
  const overview=Boolean(gamesState.access?.overview||gamesState.isStaff);
  const draftTab=$("gamesDraftTab");
  if(draftTab) draftTab.hidden=gamesState.draftStatus==="complete";
  document.querySelectorAll("[data-games-tab]").forEach(tab=>{
    const key=tab.dataset.gamesTab;
    tab.hidden=hidden || (key!=="overview"&&!full) || (key==="overview"&&!overview);
  });
  const signupTab=$("gamesSignupTab");if(signupTab)signupTab.hidden=hidden||!gamesState.signupOpen;
  renderTeamBanner();
  if(hidden){
    activeTab="overview";
    $("gamesContent").innerHTML=`<div class="games-grid"><article class="games-card full"><p class="eyebrow">IRONKIN GAMES</p><h2>Games content is currently hidden</h2><p class="games-muted">The live draft is still available while the rest of the event remains private.</p>${gamesState.draftStatus!=="complete"?`<a class="games-btn" href="/ironkin-games-draft.html">Watch Draft</a>`:""}</article></div>`;
    return;
  }
  if(!full&&activeTab!=="overview") activeTab="overview";
  document.querySelectorAll("[data-games-tab]").forEach(x=>x.classList.toggle("is-active",x.dataset.gamesTab===activeTab));
  const f={overview:renderOverview,week:renderWeek,teams:renderTeams,schedule:renderSchedule,results:renderResults,rules:renderRules}[activeTab]||renderOverview;
  $("gamesContent").innerHTML=f();bind();tick();hydrateContractPanels();hydrateTeamPanels();hydrateTestResultsPreviews();
}

function automaticResultsDialog(weekId,data){return new Promise(resolve=>{const old=document.getElementById("gamesResultsPreviewDialog");if(old)old.remove();const d=document.createElement("dialog");d.id="gamesResultsPreviewDialog";d.className="games-results-dialog";const challenges=data.challenges||[];const cards=challenges.map(c=>`<section class="games-preview-challenge"><p class="eyebrow">${esc((c.kind||"main").toUpperCase())} · AUTOMATIC</p><h3>${esc(c.name)}</h3>${(c.rows||[]).map(r=>`<div class="games-preview-row"><span class="games-preview-rank">#${r.placement}</span><strong>${esc(r.teamName)}</strong><span class="games-preview-score">${esc(r.scoreLabel)}</span><span class="games-preview-points">+${Number(r.points)||0} pts</span></div>`).join("")}${c.warning?`<div class="games-preview-warning">${esc(c.warning)}</div>`:""}</section>`).join("");d.innerHTML=`<div class="games-results-dialog-inner"><p class="eyebrow">RESULTS PREVIEW</p><h2>Review before publishing</h2><p class="games-muted">Automatic challenges have been calculated now. Publishing freezes these placements into the same official results system as reviewed submissions.</p>${cards||`<div class="games-preview-challenge"><strong>No automatic challenges this week.</strong><p class="games-muted">Reviewed manual/admin results will publish normally.</p></div>`}<div class="games-results-dialog-actions"><button class="games-btn secondary" type="button" data-preview-cancel>Cancel</button><button class="games-btn" type="button" data-preview-confirm>Publish Results</button></div></div>`;document.body.appendChild(d);d.querySelector("[data-preview-cancel]").onclick=()=>{d.close();resolve(false)};d.querySelector("[data-preview-confirm]").onclick=()=>{d.close();resolve(true)};d.onclose=()=>{setTimeout(()=>d.remove(),0)};d.showModal();});}
function bind(){document.querySelectorAll("[data-team-challenge-tab]").forEach(b=>b.onclick=()=>{activeTeamChallengeId=b.dataset.teamChallengeTab||"";render();});document.querySelectorAll("[data-end-games]").forEach(b=>b.onclick=async()=>{if(b.disabled)return;const current=standings();const likely=current[0]?.name||"the leading team";if(!confirm(`END THE IRONKIN GAMES?\n\nThis permanently finalizes the current standings, closes signups, locks the roster and declares ${likely} (or any tied leader) champion.\n\nMake sure every final result is correct before continuing.`))return;b.disabled=true;const r=await fetch("/api/admin/ironkin-games/end-games",{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"});const d=await r.json().catch(()=>({}));if(!r.ok){alert(d.error||"Could not end the Ironkin Games.");b.disabled=false;return;}alert(`${(d.champions||[]).length>1?"Co-champions":"Champion"}: ${(d.champions||[]).map(x=>x.teamName).join(" & ")||"Final standings locked"}`);activeTab="overview";document.querySelectorAll("[data-games-tab]").forEach(x=>x.classList.toggle("is-active",x.dataset.gamesTab===activeTab));await load();});document.querySelectorAll("[data-jump-tab]").forEach(b=>b.onclick=e=>{e.preventDefault();activeTab=b.dataset.jumpTab;document.querySelectorAll("[data-games-tab]").forEach(x=>x.classList.toggle("is-active",x.dataset.gamesTab===activeTab));render();});document.querySelectorAll("[data-publish-results]").forEach(b=>b.onclick=async()=>{const action=b.dataset.publishResults,weekId=b.dataset.weekId;if(action==="publish"){b.disabled=true;b.textContent="Calculating…";const pr=await fetch("/api/admin/ironkin-games/publish-results",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({weekId,action:"preview"})}),pd=await pr.json().catch(()=>({}));b.disabled=false;b.textContent="Preview Results";if(!pr.ok){alert(pd.error||"Could not calculate automatic results.");return;}if(!await automaticResultsDialog(weekId,pd))return;}else if(!confirm("Hide results for this week? This removes the week's points/results from public view without deleting them."))return;b.disabled=true;const r=await fetch("/api/admin/ironkin-games/publish-results",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({weekId,action})});const d=await r.json().catch(()=>({}));if(!r.ok){alert(d.error||"Could not update public results.");b.disabled=false;return;}await load();});document.querySelectorAll("[data-open-book-picker]").forEach(b=>b.onclick=()=>{const input=document.querySelector(`[data-book-time="${b.dataset.openBookPicker}"]`);if(!input)return;try{if(typeof input.showPicker==="function")input.showPicker();else{input.focus();input.click();}}catch{input.focus();}});document.querySelectorAll("[data-book]").forEach(b=>b.onclick=async()=>{const key=b.dataset.book,input=document.querySelector(`[data-book-time="${key}"]`);if(!input?.value){alert("Choose your team start time first.");return;}const [weekId,challengeId]=key.split("|");const r=await fetch("/api/ironkin-games/book",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({weekId,challengeId,scheduledAt:new Date(input.value).toISOString()})});const d=await r.json();if(!r.ok){alert(d.error||"Could not book slot.");return;}await load();});document.querySelectorAll("[data-boss-rush-start]").forEach(b=>b.onclick=async()=>{if(!confirm("START BOSS RUSH?\n\nYou must be fully LOGGED OUT of OSRS before continuing.\n\nWe will request a fresh WOM update and save your starting boss KCs. Your official timer begins only after that baseline is confirmed. Stay logged out until the page tells you that your baseline was captured."))return;const[weekId,challengeId]=b.dataset.bossRushStart.split("|");b.disabled=true;b.classList.add("is-loading");b.textContent="Capturing WOM Baseline…";const card=b.closest(".boss-rush-start-card");if(card){const ready=card.querySelector(".boss-rush-ready");if(ready){ready.classList.add("is-capturing");const msg=ready.querySelector("strong");if(msg)msg.textContent="Stay logged out of OSRS. We’re updating Wise Old Man and saving your starting KCs…";}}const r=await fetch("/api/ironkin-games/boss-rush-start",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({weekId,challengeId})});const d=await r.json().catch(()=>({}));if(!r.ok){alert(d.error||"Could not capture your WOM baseline. Your attempt has NOT started.");b.disabled=false;b.classList.remove("is-loading");b.textContent="Start My Attempt";if(card){const ready=card.querySelector(".boss-rush-ready");if(ready){ready.classList.remove("is-capturing");const msg=ready.querySelector("strong");if(msg)msg.textContent="You should be logged out of OSRS right now. Click “Start My Attempt” while logged out, then stay logged out until we tell you to log back in.";}}return;}await load();});document.querySelectorAll("[data-boss-rush-finish]").forEach(b=>b.onclick=async()=>{if(!confirm("Are you logged out of OSRS? WOM will update now and these results will finalize your attempt."))return;const attemptId=b.dataset.bossRushFinish;b.disabled=true;b.textContent="Updating WOM…";const r=await fetch("/api/ironkin-games/boss-rush-finish",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({attemptId})});const d=await r.json().catch(()=>({}));if(!r.ok){alert(d.error||"Could not finish Boss Rush.");b.disabled=false;b.textContent="Update WOM & Finish Attempt";return;}if(d.late)alert("Results captured, but this attempt was submitted after the 3-minute grace period and is marked for staff review.");await load();});document.querySelectorAll("[data-start]").forEach(b=>b.onclick=async()=>{if(!confirm("Start this challenge now? The timer cannot be paused or restarted."))return;const [weekId,challengeId]=b.dataset.start.split("|");b.disabled=true;const r=await fetch("/api/ironkin-games/start",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({weekId,challengeId})});const d=await r.json();if(!r.ok){alert(d.error||"Could not start challenge.");b.disabled=false;return;}await load();});document.querySelectorAll("[data-submit-form]").forEach(f=>f.onsubmit=async e=>{e.preventDefault();const [weekId,challengeId]=f.dataset.submitForm.split("|");const fd=new FormData(f);const r=await fetch("/api/ironkin-games/submit",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({weekId,challengeId,score:fd.get("score"),proofUrl:fd.get("proofUrl"),notes:fd.get("notes")})});const d=await r.json();alert(r.ok?"Result submitted for staff review.":(d.error||"Submission failed."));if(r.ok)await load();});}
function tick(){document.querySelectorAll("[data-ends]").forEach(el=>{const raw=new Date(el.dataset.ends).getTime()-Date.now();if(raw<=0){el.textContent="TIME'S UP";el.classList.add("games-timer-expired");el.removeAttribute("data-ends");if(el.dataset.bossRushAttempt){if(!el.dataset.expiredReload){el.dataset.expiredReload="1";setTimeout(()=>load(),250);}}else setTimeout(()=>load(),750);return;}const totalSeconds=Math.floor(raw/1000),m=Math.floor(totalSeconds/60),sec=totalSeconds%60;el.textContent=`${String(m).padStart(2,"0")}:${String(sec).padStart(2,"0")}`;});document.querySelectorAll("[data-grace-ends]").forEach(el=>{const raw=new Date(el.dataset.graceEnds).getTime()-Date.now();if(raw>0){const totalSeconds=Math.ceil(raw/1000),m=Math.floor(totalSeconds/60),sec=totalSeconds%60;el.textContent=`TIME'S UP - ${String(m).padStart(2,"0")}:${String(sec).padStart(2,"0")} TO SUBMIT`;}else el.textContent="GRACE PERIOD EXPIRED - STAFF REVIEW";});}
async function load(){try{const r=await fetch(`/api/ironkin-games/state${location.search||""}`,{cache:"no-store"});gamesState=await r.json();if(!r.ok)throw new Error(gamesState.error||"Could not load Games.");$("gamesStatus").textContent=gamesState.enabled?"":"Ironkin Games is currently hidden by staff.";render();}catch(e){$("gamesStatus").textContent=e.message;}}
document.querySelectorAll("[data-games-tab]").forEach(b=>b.onclick=()=>{activeTab=b.dataset.gamesTab;document.querySelectorAll("[data-games-tab]").forEach(x=>x.classList.toggle("is-active",x===b));render();});load();setInterval(tick,1000);

if(!window.__ironkinRulesModalBound){window.__ironkinRulesModalBound=true;document.addEventListener("click",e=>{const b=e.target.closest?.("[data-rules]");if(!b)return;try{openChallengeRules(b.dataset.rulesTitle||"Challenge",JSON.parse(decodeURIComponent(b.dataset.rules||"%5B%5D")));}catch(_){}});}
if(!window.__ironkinChallengeDetailsBound){window.__ironkinChallengeDetailsBound=true;document.addEventListener("click",e=>{const b=e.target.closest?.("[data-challenge-details]");if(!b)return;try{openChallengeDetails(JSON.parse(decodeURIComponent(b.dataset.challengeDetails||"%7B%7D")));}catch(_){}});}

